def solve_game(state):
    turns = 0
    while True:
        k = sum(state)
        if k == 0:
            break
        state[k-1] = 1 - state[k-1]
        turns += 1
    return turns

def average_turns(n):
    total_turns = 0
    for i in range(1 << n):
        state = [(i >> j) & 1 for j in range(n)]
        total_turns += solve_game(state)
    return total_turns / (1 << n)

for n in range(1, 7):
    print(f"n={n}, average={average_turns(n)}")

